import{_ as p,a0 as o,w as d,s as r,ao as l,I as a,x as i,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Arch Linux 中安裝 GNOME 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安裝 GNOME 桌面 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安裝 GNOME 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安裝 GNOME 桌面 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221105.3 ⭐️⭐️ How to Install GNOME Desktop in Arch Linux [Complete Guide]","title":"如何在 Arch Linux 中安裝 GNOME 桌面","tag":"202302","desc":""},"relativePath":"202302/20221105.3 ⭐️⭐️ How to Install GNOME Desktop in Arch Linux [Complete Guide].md","filePath":"[post].md"}'),h={name:"202302/20221105.3 ⭐️⭐️ How to Install GNOME Desktop in Arch Linux [Complete Guide].md"};function g(c,s,u,k,b,m){const e=o("Link");return d(),r("div",null,[s[23]||(s[23]=l('<h1 id="如何在-arch-linux-中安裝-gnome-桌面" tabindex="-1">如何在 Arch Linux 中安裝 GNOME 桌面 <a class="header-anchor" href="#如何在-arch-linux-中安裝-gnome-桌面" aria-label="Permalink to “如何在 Arch Linux 中安裝 GNOME 桌面”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/13/220203a5yb5xy24yer4atv.jpg" alt=""></p><blockquote><p>本指南解釋了在 Arch Linux 中安裝 GNOME 桌面所需的步驟。</p></blockquote><p>本指南有兩部分：第一部分是關於安裝基本的 Arch 系統；第二部分是在 Arch Linux 基礎上安裝完整的 GNOME 桌面環境。</p><h3 id="什麼是-gnome-桌面" tabindex="-1">什麼是 GNOME 桌面？ <a class="header-anchor" href="#什麼是-gnome-桌面" aria-label="Permalink to “什麼是 GNOME 桌面？”">​</a></h3><p>GNOME 是一個流行的桌面環境，是如 Ubuntu 和 Fedora 等許多基於桌面的頂級 Linux 發行版的默認桌面。幾乎所有的定製版都提供了一個 GNOME 桌面版本。</p><p>GNOME 桌面是穩定和用户友好的桌面之一，因此它被許多普通和高級用户所青睞。如果你想要一個在你進行工作時保持隱形的桌面，GNOME 就是這樣的一個。它不會在你工作時妨礙你。因此，儘管有許多關於 GNOME 3（目前的版本）速度慢、資源重等爭議，它仍然是許多人的流行和默認選擇。</p><p>説了這麼多，讓我們來看看如何在裸機 Arch 中安裝 GNOME 桌面。</p><h3 id="在-arch-linux-中安裝-gnome-桌面" tabindex="-1">在 Arch Linux 中安裝 GNOME 桌面 <a class="header-anchor" href="#在-arch-linux-中安裝-gnome-桌面" aria-label="Permalink to “在 Arch Linux 中安裝 GNOME 桌面”">​</a></h3><h4 id="第一部分-安裝-arch-linux" tabindex="-1">第一部分：安裝 Arch Linux <a class="header-anchor" href="#第一部分-安裝-arch-linux" aria-label="Permalink to “第一部分：安裝 Arch Linux”">​</a></h4><p>如果你已經安裝了 Arch Linux，你可以跳過這一步，直接進入下面安裝 GNOME 桌面部分。</p>',11)),a("p",null,[s[1]||(s[1]=i("要快速安裝 Arch Linux 基礎版，請遵循以下步驟。你也可以訪問 ",-1)),n(e,{href:"https://www.debugpoint.com/2020/11/install-arch-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("該指南",-1)])]),_:1}),s[2]||(s[2]=i("，瞭解如何將 Arch Linux 安裝為雙啓動或在虛擬機中的完整教程。",-1))]),s[24]||(s[24]=a("p",null,[i("本文下面介紹的步驟是安裝 Arch 的傳統方式。新手請按照下面的指南鏈接，以更現代的方式使用 "),a("code",null,"archinstall"),i(" 腳本。完成後，回來通過第二部分的步驟繼續 GNOME 安裝。")],-1)),a("blockquote",null,[a("p",null,[a("strong",null,[n(e,{href:"https://www.debugpoint.com/archinstall-guide/"},{default:t(()=>[...s[3]||(s[3]=[i("現代方式：使用 archinstall 腳本安裝（推薦）",-1)])]),_:1})])])]),s[25]||(s[25]=a("h5",{id:"傳統方式-下載-arch-linux",tabindex:"-1"},[i("傳統方式：下載 Arch Linux "),a("a",{class:"header-anchor",href:"#傳統方式-下載-arch-linux","aria-label":"Permalink to “傳統方式：下載 Arch Linux”"},"​")],-1)),s[26]||(s[26]=a("p",null,"從下面的鏈接下載 Arch Linux 的 .iso 文件。它也提供了磁力鏈接和種子鏈接。下載後，將 ISO 寫入 USB 驅動器。然後從該驅動器啓動。",-1)),a("blockquote",null,[a("p",null,[a("strong",null,[n(e,{href:"https://www.archlinux.org/download/"},{default:t(()=>[...s[4]||(s[4]=[i("下載 Arch Linux",-1)])]),_:1})])])]),s[27]||(s[27]=l(`<p>如果你打算通過 GNOME Boxes、virt-manager 把它安裝成一個虛擬機鏡像，那麼你就不需要把它寫入 U 盤。</p><h5 id="啓動和配置分區" tabindex="-1">啓動和配置分區 <a class="header-anchor" href="#啓動和配置分區" aria-label="Permalink to “啓動和配置分區”">​</a></h5><p>從 Arch Linux ISO 啓動後，你必須運行一系列的命令來安裝基本系統。</p><p>首先，運行下面的命令，找出設備標識符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk -l</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/fdisk-l-before.jpg" alt="之前的 fdisk -l"></p><p>然後用設備標識符，運行下面的命令，開始對你的磁盤進行分區。請確保根據你的系統改變 <code>/dev/sda</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cfdisk /dev/sda</span></span></code></pre></div><p>在下一個提示中選擇 <code>label type = dos</code>。</p><p>選擇自由空間，並從底部選擇 “<ruby>新建<rt>New</rt></ruby>” 選項。在這個例子中，我將創建三個分區，如下圖所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/sda1 - 1G - for /boot</span></span>
<span class="line"><span>/dev/sda2 - 5G - for root</span></span>
<span class="line"><span>/dev/sda3 - 1G - for swap</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/cfdisk-1024x159.jpg" alt="cfdisk"></p><p>在下一個屏幕中，提供引導分區的分區大小（在這個例子中，我給出了 1GB）。選擇它作為主分區。</p><p>對大小為 5GB 的主根分區重複同樣的步驟。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Swap-parition-type-change.jpg" alt="改變為交換分區類型"></p><p>用同樣的步驟創建一個大小為 1G 的交換分區（你可以根據你的需要改變它）。創建交換分區後，確保在底部選擇 “<ruby>類型<rt>Type</rt></ruby>”，並用 “Linux Swap/Solaris” 選項將其標記為交換分區。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/final-partition-list-in-cfdisk-1024x178.jpg" alt="cfdisk 中的最終分區列表"></p><p>一旦完成，使用底部的 “<ruby>寫入<rt>Write</rt></ruby>” 選項將變化寫入磁盤。<strong>確保你在寫入前做了備份，因為這是你係統中的一個永久性變化。</strong></p><p>在你繼續之前，運行下面的命令來檢查。你可以看到在這個例子中，有三個分區被列出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk -l</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/final-partition-list-in-fdisk.jpg" alt="fdisk 中的最終分區列表"></p><p>依次運行下面的命令，在上面新創建的分區中格式化並創建一個 ext4 文件系統。請確保你根據你的需要改變 <code>/dev/sda1</code> 和 <code>/dev/sda2</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs.ext4 /dev/sda1</span></span>
<span class="line"><span>mkfs.ext4 /dev/sda2</span></span>
<span class="line"><span>mkswap /dev/sda3</span></span>
<span class="line"><span>swapon /dev/sda3</span></span></code></pre></div><p>完成後，裝載系統並創建必要的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount /dev/sda2 /mnt</span></span>
<span class="line"><span>mkdir /mnt/boot /mnt/var /mnt/home</span></span>
<span class="line"><span>mount /dev/sda1 /mnt/boot</span></span></code></pre></div><p>同樣，確保你根據你的系統改變 <code>/dev/sda1</code>、<code>/dev/sda2</code> 和 <code>/dev/sda3</code>。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/prepare-file-system.jpg" alt="準備文件系統"></p><h5 id="安裝基礎系統" tabindex="-1">安裝基礎系統 <a class="header-anchor" href="#安裝基礎系統" aria-label="Permalink to “安裝基礎系統”">​</a></h5>`,28)),a("p",null,[s[6]||(s[6]=i("我希望你已經連接到互聯網了。如果沒有，請嘗試使用 USB 網卡或 Arch 安裝程序自動配置和檢測的有線網絡連接。如果你沒有可用的有線連接，請按照 ",-1)),n(e,{href:"https://www.debugpoint.com/2020/11/connect-wifi-terminal-linux/"},{default:t(()=>[...s[5]||(s[5]=[i("該指南",-1)])]),_:1}),s[7]||(s[7]=i(" 使用 Arch Linux 安裝程序配置一個無線或 Wi-Fi 網絡。",-1))]),s[28]||(s[28]=l(`<p>依次運行下面的命令，將基本系統安裝到已安裝的分區中。下載的大小約為 400MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Syy</span></span>
<span class="line"><span>pacstrap /mnt base base-devel linux linux-firmware nano dhcpcd net-tools grub</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Install-base-system-1024x205.jpg" alt="安裝基本系統"></p><p>一旦完成，就會生成文件系統表，沒有它你就無法啓動系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>genfstab -U /mnt &gt;&gt; /mnt/etc/fstab</span></span></code></pre></div><h5 id="配置基礎系統" tabindex="-1">配置基礎系統 <a class="header-anchor" href="#配置基礎系統" aria-label="Permalink to “配置基礎系統”">​</a></h5><p>依次按照下面的命令來配置基本系統。這涉及到設置你的地域、語言、添加一個登錄用户，以及設置互聯網：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arch-chroot /mnt</span></span>
<span class="line"><span>nano /etc/locale.gen</span></span></code></pre></div><p>通過去掉開頭的 <code>#</code> 來取消對你所選擇的 <ruby>語言環境<rt>locale</rt></ruby> 的註釋。在本指南中，我選擇了 <code>en_US.UTF-8 UTF-8</code>，按 <code>CTRL+O</code>、回車和 <code>CTRL+X</code> 退出 nano。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/change-locale.jpg" alt="本地化"></p><p>使用以下方法生成語言環境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locale-gen</span></span></code></pre></div><p>如果你不想手動去 <code>/etc/locale.gen</code> 設置語言，也可以使用以下命令設置語言：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo LANG=en_US.UTF-8 &gt; /etc/locale.conf</span></span>
<span class="line"><span>export LANG=en_US.UTF-8</span></span></code></pre></div><p>設置當地的時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /usr/share/zoneinfo/America/New_York /etc/localtime</span></span></code></pre></div><p>同樣，你可以根據你的需要來選擇它們。你可以通過以下命令列出當地的時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /usr/share/zoneinfo</span></span>
<span class="line"><span>ls /usr/share/zoneinfo/America</span></span></code></pre></div><p>設置硬件時鐘，創建一個主機名，並使用以下命令依次啓用互聯網的 DHCP。你可以根據你的想法，將 <code>arindam-pc</code> 改為任何主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hwclock --systohc --utc</span></span>
<span class="line"><span>echo arindam-pc &gt; /etc/hostname</span></span>
<span class="line"><span>systemctl enable dhcpcd</span></span></code></pre></div><p>下一步是設置根用户的密碼，創建一個管理員用户，並在 <code>sudoers</code> 文件中添加該用户。</p><p>依次按照下面的命令進行操作。請確保根據你的需要將用户名從 <code>debugpoint</code> 改為其他名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd rootuseradd -m -g users -G wheel -s /bin/bash debugpointpasswd debugpoint</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/create-user.jpg" alt="創建用户"></p><p>打開 <code>sudoers</code> 文件，添加以下幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano /etc/sudoers</span></span></code></pre></div><p>添加以下幾行。由於你已經創建了 <code>root</code> 用户，該條目應該已經有了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root ALL=(ALL) ALL</span></span>
<span class="line"><span>debugpoint ALL=(ALL) ALL</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/update-sudoers-file.jpg" alt="更改 sudoer 文件"></p><p>依次使用如下命令安裝 Grub，設置初始化 Ramdisk 環境，卸載系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grub-install /dev/sda </span></span>
<span class="line"><span>grub-mkconfig -o /boot/grub/grub.cfg</span></span>
<span class="line"><span>mkinitcpio -p linux</span></span>
<span class="line"><span>exit</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/configure-grub-1024x639.jpg" alt="配置 Grub"></p><p>然後重新啓動你的系統。如果你是在一個物理系統中安裝的，在這一步要拔掉 USB 介質。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>umount /mnt/boot</span></span>
<span class="line"><span>umount /mnt</span></span>
<span class="line"><span>reboot</span></span></code></pre></div><p>你現在已經成功地安裝了 Arch Linux 基本系統。現在是安裝完整的 GNOME 桌面的時候了。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Arch-is-installed.jpg" alt="Arch 安裝好了"></p><h4 id="第二部分-在-arch-linux-中安裝-gnome" tabindex="-1">第二部分：在 Arch Linux 中安裝 GNOME <a class="header-anchor" href="#第二部分-在-arch-linux-中安裝-gnome" aria-label="Permalink to “第二部分：在 Arch Linux 中安裝 GNOME”">​</a></h4><p>重啓後，從 Grub 中選擇 Arch Linux。在 Arch Linux 的提示符下，開始依次運行以下命令。這些命令安裝 Xorg 服務器、顯示管理器、GNOME 桌面組件、控制器包和其他應用程序。</p><p>所有的命令都使用默認值，即在要求時按回車。</p><p>安裝 Xorg 服務器。安裝大小約為 80MB:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed xorg</span></span></code></pre></div><p>安裝顯示管理器、GNOME 桌面。安裝大小約為 300MB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed gnome gnome-tweaks nautilus-sendto gnome-nettool gnome-usage gnome gnome-multi-writer adwaita-icon-theme xdg-user-dirs-gtk fwupd arc-gtk-theme seahosrse gdm</span></span></code></pre></div><p>上面的安裝會要求提供幾個軟件包的選項。選擇你想要的任何一個。如果你不確定，在詢問時選擇 “jack”、“noto-sans” 和 “xdg-portal-desktop-gnome”。</p><p>安裝應用程序。這只是一個參考。你也可以安裝你所需要的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed firefox vlc filezilla leafpad xscreensaver archlinux-wallpaper</span></span></code></pre></div><p>現在是時候把顯示管理器和網絡管理器作為服務啓用了。這樣，下次登錄時，它們就可以由 systemd 自動運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable gdm</span></span>
<span class="line"><span>systemctl enable NetworkManager</span></span></code></pre></div><p>使用 <code>reboot</code> 命令重新啓動系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Arch-Linux-Running-GNOME-43-Desktop-1024x636.jpg" alt="Arch Linux 運行 GNOME 43 桌面"></p><p>如果一切順利，你應該在 GNOME 桌面上看到一個漂亮的登錄提示。使用你剛剛創建的憑證登錄。迎接你的應該是 Arch Linux 漂亮而乾淨的 GNOME 43 桌面。</p><p>我希望這個指南能幫助你在裸機 Arch 安裝 GNOME 桌面。</p><hr>`,54)),a("p",null,[s[9]||(s[9]=i("via: ",-1)),n(e,{href:"https://www.debugpoint.com/gnome-arch-linux-install/"},{default:t(()=>[...s[8]||(s[8]=[i("https://www.debugpoint.com/gnome-arch-linux-install/",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=i("作者：",-1)),n(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...s[10]||(s[10]=[i("Arindam",-1)])]),_:1}),s[15]||(s[15]=i(" 選題：",-1)),n(e,{href:"https://github.com/lkxed"},{default:t(()=>[...s[11]||(s[11]=[i("lkxed",-1)])]),_:1}),s[16]||(s[16]=i(" 譯者：",-1)),n(e,{href:"https://github.com/Chao-zhi"},{default:t(()=>[...s[12]||(s[12]=[i("Chao-zhi",-1)])]),_:1}),s[17]||(s[17]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[i("LCTT",-1)])]),_:1}),s[21]||(s[21]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[i("Linux中國",-1)])]),_:1}),s[22]||(s[22]=i(" 榮譽推出",-1))])])}const y=p(h,[["render",g]]);export{w as __pageData,y as default};
